 "<span style=\"font-family:'Bebas Neue', sans-serif;font-size:84px;color:#fff\"><span style=\"text-shadow:5px 5px 0 #111111\">¡POW!</span></span>": "<span style=\"font-family:'Bebas Neue', sans-serif;font-size:84px;color:#fff\"><span style=\"text-shadow:5px 5px 0 #111111\">POW!</span></span>",
